// React hook wrapper for the ToastModule
import { useEffect, useCallback } from 'react';
import { ToastModule } from './native/ToastModule';

export function useToast() {
  const show = useCallback((message, durationMs = 3000) => {
    ToastModule.showToast(message, durationMs);
  }, []);

